which sqlite3 2>/dev/null || apt list --installed 2>/dev/null | grep sqlite; node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables);
" 2>/dev/null || echo "no better-sqlite3"

npm install better-sqlite3 2>/dev/null 1>/dev/null && node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', JSON.stringify(tables, null, 2));
for (const t of tables) {
  if (t.name.toLowerCase().includes('remind')) {
    const rows = db.prepare('SELECT * FROM ' + t.name).all();
    console.log('\\n' + t.name + ':', JSON.stringify(rows, null, 2));
  }
}
"

